import React from 'react';

export interface UserBadgeProps {
  displayName: string;
  avatarUrl: string;
  size?: number;
}

export function UserBadge({ displayName, avatarUrl, size = 32 }: UserBadgeProps) {
  return (
    <span style={{ display: 'inline-flex', alignItems: 'center', gap: 8 }}>
      {/* Empty alt: the adjacent display name already identifies the user. */}
      <img
        src={avatarUrl}
        alt=""
        width={size}
        height={size}
        style={{ borderRadius: '50%', objectFit: 'cover' }}
      />
      <span>{displayName}</span>
    </span>
  );
}

export default UserBadge;
