import styles from './UserBadge.module.css';

export interface UserBadgeProps {
  displayName: string;
  avatarUrl: string;
  onSelect?: () => void;
}

export function UserBadge({ displayName, avatarUrl, onSelect }: UserBadgeProps) {
  const content = (
    <>
      {/* The display name is rendered next to the avatar, so the image is decorative. */}
      <img className={styles.avatar} src={avatarUrl} alt="" width={32} height={32} />
      <span className={styles.displayName}>{displayName}</span>
    </>
  );

  if (onSelect) {
    return (
      <button type="button" className={styles.badgeButton} onClick={onSelect}>
        {content}
      </button>
    );
  }

  return <span className={styles.badge}>{content}</span>;
}
